import java.util.Properties

// Watch Face Format face: resources only, no code (hasCode=false in the manifest).
// res/raw/watchface.xml and the moon sprites are GENERATED by tools/gen_face.py; edit that, not the outputs.
plugins {
    alias(libs.plugins.android.application)
}

android {
    enableKotlin = false
    namespace = "com.analemmic.nightwatch.face"
    compileSdk = 37

    defaultConfig {
        applicationId = "com.analemmic.nightwatch.face"
        // WFF v4 requires Wear OS 6 / API 36. Keep minSdk matched to the format version.
        minSdk = 36
        targetSdk = 37
        versionCode = 1
        versionName = "1.0.0"
    }

    // Release signing: Play upload key, read from keystore.properties at the project root (git-ignored; never commit it).
    // Without that file, release builds come out unsigned. See RELEASE.md.
    val ks = rootProject.file("keystore.properties")
    if (ks.exists()) {
        val p = Properties().apply { ks.inputStream().use { load(it) } }
        signingConfigs.create("upload") {
            storeFile = rootProject.file(p.getProperty("storeFile"))
            storePassword = p.getProperty("storePassword")
            keyAlias = p.getProperty("keyAlias")
            keyPassword = p.getProperty("keyPassword")
        }
    }

    buildTypes {
        debug {
            isMinifyEnabled = true
        }
        release {
            isMinifyEnabled = true
            isShrinkResources = false // resources are referenced by name from watchface.xml
            signingConfig = signingConfigs.findByName("upload")
        }
    }
}
